import{_ as r,a0 as p,w as o,s as P,ao as s,I as n,x as e,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"用 PGP 保護代碼完整性（一）： 基本概念和工具 | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保護代碼完整性（一）： 基本概念和工具 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保護代碼完整性（一）： 基本概念和工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保護代碼完整性（一）： 基本概念和工具 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180214 Protecting Code Integrity with PGP - Part 1- Basic Concepts and Tools","title":"用 PGP 保護代碼完整性（一）： 基本概念和工具","tag":"201804","desc":""},"relativePath":"201804/20180214 Protecting Code Integrity with PGP - Part 1- Basic Concepts and Tools.md","filePath":"[post].md"}'),d={name:"201804/20180214 Protecting Code Integrity with PGP - Part 1- Basic Concepts and Tools.md"};function u(g,i,h,G,b,k){const l=p("Link");return o(),P("div",null,[i[25]||(i[25]=s(`<h1 id="用-pgp-保護代碼完整性-一-基本概念和工具" tabindex="-1">用 PGP 保護代碼完整性（一）： 基本概念和工具 <a class="header-anchor" href="#用-pgp-保護代碼完整性-一-基本概念和工具" aria-label="Permalink to “用 PGP 保護代碼完整性（一）： 基本概念和工具”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/pgp-security.jpg?itok=lulwyzYc" alt=""></p><p>在本系列文章中，我們將深度探討如何使用 PGP 確保軟件完整性。這些文章將為工作於自由軟件項目的開發者提供實用指南，並且將包含以下主題：</p><ol><li>PGP 基礎和最佳實踐</li><li>如何用 Git 使用 PGP</li><li>如何保護你的開發者賬户</li></ol><p>我們使用與“Freedom”含義相同的詞項 “Free”，但這個系列中列出的指南也可以被任何其它類型的依賴於分佈式團隊開發者貢獻的軟件中。如果你編寫進入公共源倉庫的代碼，你可以從瞭解和遵循這篇指南中受益。</p><h3 id="結構" tabindex="-1">結構 <a class="header-anchor" href="#結構" aria-label="Permalink to “結構”">​</a></h3><p>每節分為兩個部分：</p><ul><li>適用於你項目需求的清單</li><li>形式自由的考慮事項的列表，解釋這些決定取決於什麼，並伴隨着配置指令</li></ul><h4 id="清單優先級" tabindex="-1">清單優先級 <a class="header-anchor" href="#清單優先級" aria-label="Permalink to “清單優先級”">​</a></h4><p>每個清單中各項包含着優先級，用來幫助指導你的決定：</p><ul><li>（必要）該項一定要排在考慮事項列表的前面。如果沒有這樣做，它們將給提交到開源項目中的代碼帶來高風險。</li><li>（推薦）包含該項將提升整體安全性，但會影響你與工作環境的交互方式，並且可能需要學習新的習慣或者放棄舊的習慣。</li></ul><p>記住，這些只是指導。如果你感到這些優先級不能反映你項目提交的安全，你應該根據自己的需要調整它們。</p><h3 id="pgp-基本概念和工具" tabindex="-1">PGP 基本概念和工具 <a class="header-anchor" href="#pgp-基本概念和工具" aria-label="Permalink to “PGP 基本概念和工具”">​</a></h3><h4 id="清單" tabindex="-1">清單 <a class="header-anchor" href="#清單" aria-label="Permalink to “清單”">​</a></h4><ol><li>理解 PGP 在自由軟件開發中的作用 （必要）</li><li>理解<ruby>公鑰密碼學<rt>Public Key Cryptography</rt></ruby>的基礎知識 （必要）</li><li>理解 PGP 加密和簽名的不同 （必要）</li><li>理解 PGP <ruby>密鑰身份<rt>key identities</rt></ruby> （必要）</li><li>理解 PGP <ruby>密鑰有效性<rt>key validity</rt></ruby> （必要）</li><li>安裝 GnuPG 工具（版本 2.x） （必要）</li></ol><h4 id="考慮事項" tabindex="-1">考慮事項 <a class="header-anchor" href="#考慮事項" aria-label="Permalink to “考慮事項”">​</a></h4><p>自由軟件社區長期依賴於 PGP 確保它生產的軟件產品的真實性和完整性。你可能沒有注意到，但無論你是一個 Linux 、Mac 和 Windowas 用户，你都曾依賴 PGP 來確保你電腦環境的完整性：</p><ul><li>Linux 發行版依賴 PGP 來確保當二進制或者原代碼包從被生產出來到被終端用户安裝之間沒被更改過</li><li>自由軟件項目通常會伴隨發行軟件的存檔提供分離的 PGP 簽名，使得下游的項目可以在把下載的版本集成到自己的分佈式下載之前，驗證下載版本的完整性。</li><li>自由軟件項目通常依賴代碼本身的 PGP 簽名來跟蹤起源，並驗證項目開發者提交的代碼的完整性</li></ul><p>這與工作於專有平台的程序員使用的開發者證書或代碼簽名機制非常相似。實際上，這兩種技術背後的核心概念非常相似 —— 儘管它們在實現的技術層面和它們委託信任方式的大多不同。PGP 不依賴於集中式認證機構，而是讓每個用户為每個證書賦予自己的信任。</p><p>我們的目標是使你的項目通過使用 PGP 來進行代碼起源和完整性追蹤，遵循最佳實踐並遵守基本的安全預防措施。</p><h4 id="極其基本的-pgp-操作概括" tabindex="-1">極其基本的 PGP 操作概括 <a class="header-anchor" href="#極其基本的-pgp-操作概括" aria-label="Permalink to “極其基本的 PGP 操作概括”">​</a></h4><p>你不需要知道 PGP 如何工作的具體細節 —— 理解核心概念足以成功地達到我們的目的。PGP 依賴於公鑰密碼學來將明文轉換為密文。這個過程需要兩種不同的密鑰：</p><ul><li>公鑰，被所有人知道</li><li>私鑰，只被擁有者知道</li></ul><h5 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to “加密”">​</a></h5><p>對加密來説，PGP 使用擁有者的公鑰創造一條只能通過擁有者私鑰解密的消息：</p><ol><li>發送者生成一個隨機的加密密鑰（“會話密鑰”）</li><li>發送者使用該會話密鑰（使用對稱算法）加密內容</li><li>發送者使用接收者的 PGP 公鑰加密會話密鑰</li><li>發送者向接收者發送加密後的內容和加密後的會話密鑰</li></ol><p>要解密：</p><ol><li>接收者使用他們的 PGP 私鑰解密會話密鑰</li><li>接收者使用會話密鑰解密消息的內容</li></ol><h5 id="簽名" tabindex="-1">簽名 <a class="header-anchor" href="#簽名" aria-label="Permalink to “簽名”">​</a></h5><p>為了創建簽名，PGP 私鑰或公鑰會以相反的方式使用：</p><ol><li>簽名者生成內容的校檢和哈希</li><li>簽名者使用自己的 PGP 私鑰來加密該校檢和</li><li>簽名者伴隨內容提供加密後的校檢和</li></ol><p>要驗證簽名：</p><ol><li>驗證者生成自己的內容校檢和哈希</li><li>驗證者使用簽名者的 PGP 公鑰來解密提供的校檢和</li><li>如果校檢和匹配，就驗證了內容的完整性</li></ol><h5 id="結合使用" tabindex="-1">結合使用 <a class="header-anchor" href="#結合使用" aria-label="Permalink to “結合使用”">​</a></h5><p>通常，加密消息也被髮送者自己的 PGP 密鑰簽名。無論何時使用加密消息，這應當是默認的，因為沒有認證的加密沒有很大意義（除非你是一個告密者或秘密代理並且需要可行的可否認性）</p><h4 id="理解密鑰身份" tabindex="-1">理解密鑰身份 <a class="header-anchor" href="#理解密鑰身份" aria-label="Permalink to “理解密鑰身份”">​</a></h4><p>每個 PGP 密鑰必須有一個或多個與之關聯的身份。通常，“<ruby>身份<rt>Identity</rt></ruby>”指的是以下格式中的人物全名和郵件地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Alice Engineer &lt;alice.engineer@example.com&gt;</span></span></code></pre></div><p>有時也會在括號中包含説明，來告訴終端用户關於該特定密鑰的更多信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Bob Designer (obsolete 1024-bit key) &lt;bob.designer@example.com&gt;</span></span></code></pre></div><p>由於人們可以和多個職業和個人實體相關聯，因此在同一密鑰上可以有多個身份：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Alice Engineer &lt;alice.engineer@example.com&gt;</span></span>
<span class="line"><span>Alice Engineer &lt;aengineer@personalmail.example.org&gt;</span></span>
<span class="line"><span>Alice Engineer &lt;webmaster@girlswhocode.example.net&gt;</span></span></code></pre></div><p>當使用多個身份時，其中之一將被標記為“<ruby>primary identity<rt>主要身份</rt></ruby>”來讓檢索更簡單。</p><h4 id="理解密鑰有效性" tabindex="-1">理解密鑰有效性 <a class="header-anchor" href="#理解密鑰有效性" aria-label="Permalink to “理解密鑰有效性”">​</a></h4><p>為了能使用其他人的公鑰來加密或驗證，你需要確保它確實屬於正確的人（Alice）而不屬於冒牌的（Eve）。在 PGP 中，這被稱為“密鑰有效性”：</p><ul><li>有效性：<ruby>完全<rt>full</rt></ruby> -- 意味着非常確認該密鑰屬於 Alice</li><li>有效性：<ruby>臨界<rt>marginal</rt></ruby> -- 意味着大致確認該密鑰屬於 Alice</li><li>有效性：<ruby>未知<rt>unknown</rt></ruby> -- 意味着不確認該密鑰是否屬於 Alice</li></ul><h4 id="web-of-trust-wot-與-trust-on-first-use-tofu" tabindex="-1">Web of Trust （WOT） 與 Trust on First Use (TOFU) <a class="header-anchor" href="#web-of-trust-wot-與-trust-on-first-use-tofu" aria-label="Permalink to “Web of Trust （WOT）  與 Trust on First Use (TOFU)”">​</a></h4><p>PGP 使用了一種信任委託機制叫“Web of Trust”。它的核心是嘗試替代 HTTPS/TLS 世界中對集中式認證機構的需求。PGP 把這個責任交給了每個用户，而不是各種軟件開發商來決定誰應該是你的可信認證實體。</p><p>不幸的是，很少有人理解 Web of Trust 的是如何工作的，能使用它的人更少。它仍然是 OpenPGP 規範的一個重要方面，但 GnuPG 的近期版本（2.2 及以上）已經實現了一種替代機制叫“Trust on First Use”(TOFU)。</p><p>你可以把 TOFU 當作類似 SSH 的信任方式。使用 SSH，當你第一次連接到遠程系統，它的密鑰指紋會被記錄和保存。如果將來密鑰改變，SSH 客户端將會提醒你並拒絕連接，迫使你決定是否信任已改變的的密鑰。</p><p>同樣，當你第一次導入某人的 PGP 密鑰，它被假定可信。如果在將來的任何時候，GnuPG 碰巧發現另一同樣身份的密鑰，過去導入的密鑰和新密鑰都將被標記為無效，並且你需要手動指出保留哪個。</p><h4 id="安裝-openpgp-軟件" tabindex="-1">安裝 OpenPGP 軟件 <a class="header-anchor" href="#安裝-openpgp-軟件" aria-label="Permalink to “安裝 OpenPGP 軟件”">​</a></h4><p>首先，理解 PGP、OpenPGP、GnuPG 和 gpg 之間的不同很重要：</p><ul><li>PGP （“Pretty Good Privacy”） 是最初商業軟件的名字</li><li>OpenPGP 是與最初 PGP 工具兼容的 IETF 標準</li><li>GnuPG （“Gnu Privacy Guard”）是實現了 OpenPGP 標準的自由軟件</li><li>GnuPG 的命令列工具稱為 “gpg”</li></ul><p>今天，“PGP”這個詞幾乎被普遍用來表示開放的 OpenPGP 標準，而不是最初的商業軟件，因此“PGP”和“OpenPGP”是可以互換的。“GnuPG”和“pgp”這兩個詞應該僅在提及工具時使用，而不用於它們產生的輸出或它們實現的 OpenPGP 功能。舉例：</p><ul><li>PGP（而非 GnuPG 或 GPG）密鑰</li><li>PGP（而非 GnuPG 或 GPG）簽名</li><li>PGP（而非 GnuPG 或 GPG）密鑰服務器</li></ul><p>理解這一點應該可以保護你免受來自你遇到的其他 PGP 用户“實際上”不可避免的迂腐。</p><h5 id="安裝-gnupg" tabindex="-1">安裝 GnuPG <a class="header-anchor" href="#安裝-gnupg" aria-label="Permalink to “安裝 GnuPG”">​</a></h5>`,58)),n("p",null,[i[2]||(i[2]=e("如果你正在使用 Linux，你應該已經安裝過了 GnuPG。在 Mac 上，你應該安裝 ",-1)),t(l,{href:"https://gpgtools.org/"},{default:a(()=>[...i[0]||(i[0]=[e("GPG-Suite",-1)])]),_:1}),i[3]||(i[3]=e("，或者使用 ",-1)),i[4]||(i[4]=n("code",null,"brew",-1)),i[5]||(i[5]=e(" 安裝 ",-1)),i[6]||(i[6]=n("code",null,"gnupg2",-1)),i[7]||(i[7]=e("。在 Windows 上，你應該安裝 ",-1)),t(l,{href:"https://www.gpg4win.org/"},{default:a(()=>[...i[1]||(i[1]=[e("GPG4Win",-1)])]),_:1}),i[8]||(i[8]=e("，並且為了可以工作，你可能需要調整指南中的部分命令，除非你設置了類似 Unix 的環境。對其他平台來説，你需要自行查找正確的地址來下載和安裝 GnuPG。",-1))]),i[26]||(i[26]=s('<h5 id="gnupg-1-vs-2" tabindex="-1">GnuPG 1 vs. 2 <a class="header-anchor" href="#gnupg-1-vs-2" aria-label="Permalink to “GnuPG 1 vs. 2”">​</a></h5><p>GnuPG v.1 和 GnuPG v.2 都實現了同樣的標準，但它們提供不兼容的庫和命令列工具，所以許多發行版都帶有了舊的版本 1 和最新的版本 2。你需要確保你總是使用 GnuPG v.2。</p><p>首先，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --version | head -n1</span></span></code></pre></div><p>如果你看到 <code>gpg (GnuPG) 1.4.x</code>，説明你正使用 GnuPG v.1。嘗試下 <code>gpg2</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg2 --version | head -n1</span></span></code></pre></div><p>如果你看到 <code>gpg (GnuPG) 2.x.x</code>，説明你可以繼續了。這篇指南將假設你使用 GnuPG 2.2 版本（或更新）。如果你正使用 GnuPG 的 2.0 版本，本指南中某些命令可能無效，你應該考慮安裝 GnuPG 最新的 2.2 版本</p><h5 id="確保你總是使用-gnupg-v-2" tabindex="-1">確保你總是使用 GnuPG v.2 <a class="header-anchor" href="#確保你總是使用-gnupg-v-2" aria-label="Permalink to “確保你總是使用 GnuPG v.2”">​</a></h5><p>如果你 <code>gpg</code> 和 <code>gpg2</code> 命令都有，你應該確保總是使用 GnuPG v.2，而不是舊的版本。你可以通過設置別名來確保這一點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias gpg=gpg2</span></span></code></pre></div><p>你可以把它放在你的 <code>.bashrc</code> 中，以確保它在你使用 <code>gpg</code> 命令時總是被加載。</p><p>在本系列的第 2 部分中，我們將介紹生成和保護你的 PGP 主密鑰的基本步驟。</p>',12)),n("p",null,[i[10]||(i[10]=e("通過 Linux 基金會和 edX 的免費",-1)),t(l,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:a(()=>[...i[9]||(i[9]=[e("“Introduction to Linux” ",-1)])]),_:1}),i[11]||(i[11]=e("課程瞭解關於 Linux 的更多信息。",-1))]),i[27]||(i[27]=n("hr",null,null,-1)),n("p",null,[i[13]||(i[13]=e("via: ",-1)),t(l,{href:"https://www.linux.com/blog/learn/2018/2/protecting-code-integrity-pgp-part-1-basic-pgp-concepts-and-tools"},{default:a(()=>[...i[12]||(i[12]=[e("https://www.linux.com/blog/learn/2018/2/protecting-code-integrity-pgp-part-1-basic-pgp-concepts-and-tools",-1)])]),_:1})]),n("p",null,[i[17]||(i[17]=e("作者：",-1)),t(l,{href:"https://www.linux.com/users/mricon"},{default:a(()=>[...i[14]||(i[14]=[e("Konstantin Ryabitsev",-1)])]),_:1}),i[18]||(i[18]=e(" 譯者：",-1)),t(l,{href:"https://github.com/kimii"},{default:a(()=>[...i[15]||(i[15]=[e("kimii",-1)])]),_:1}),i[19]||(i[19]=e(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:a(()=>[...i[16]||(i[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[i[22]||(i[22]=e("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[20]||(i[20]=[e("LCTT",-1)])]),_:1}),i[23]||(i[23]=e(" 原創編譯，",-1)),t(l,{href:"https://linux.cn/"},{default:a(()=>[...i[21]||(i[21]=[e("Linux中國",-1)])]),_:1}),i[24]||(i[24]=e(" 榮譽推出",-1))])])}const y=r(d,[["render",u]]);export{m as __pageData,y as default};
